use super::*;

/// Every lane that has ever been written, with how many records it holds.
pub fn lanes(conn: &Connection) -> Result<Vec<(String, i64)>, String> {
    let mut st = conn
        .prepare("SELECT lane, COUNT(DISTINCT id) FROM record_revs GROUP BY lane ORDER BY lane")
        .map_err(|e| e.to_string())?;
    let rows: Vec<(String, i64)> = st
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
        .map_err(|e| e.to_string())?
        .collect::<Result<_, _>>()
        .map_err(|e| e.to_string())?;
    Ok(rows)
}
